348		if len(out.FinalLog) != 1 {
349			t.Fatalf("log changed: %+v", out.FinalLog)
350		}
351	
352		// 非法请求之后，下一条合法请求仍正常处理。
353		out = run(t, initial,
354			AppendRequest{Term: 9, PrevLogIndex: 1, PrevLogTerm: 2,
355				Entries: []LogEntry{entry(5, 9, "x")}},
356			AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 1,
357				Entries: []LogEntry{entry(2, 3, "b")}},
358		)
359		if !out.Results[1].Accepted {
360			t.Fatalf("valid request after invalid one rejected: %+v", out.Results[1])
361		}
362		if out.Results[1].Term != 3 {
363			t.Fatalf("term = %d, want 3", out.Results[1].Term)
364		}
365	}
366	
367	func TestInvalidInitialStates(t *testing.T) {
368		cases := []struct {
369			name      string
370			initial   InitialState
371			fragments []string
372		}{
373			{"negative term", InitialState{CurrentTerm: -1}, []string{"currentTerm"}},
374			{"negative commit", InitialState{CurrentTerm: 2, CommittedIndex: -1}, []string{"committedIndex"}},
375			{"commit beyond log", InitialState{CurrentTerm: 2, CommittedIndex: 2,
376				Log: []LogEntry{entry(1, 2, "a")}}, []string{"committedIndex", "exceeds"}},
377			{"index gap", InitialState{CurrentTerm: 2,
378				Log: []LogEntry{entry(2, 2, "a")}}, []string{"index"}},
379			{"zero term entry", InitialState{CurrentTerm: 2,
380				Log: []LogEntry{entry(1, 0, "a")}}, []string{"term"}},
381			{"decreasing terms", InitialState{CurrentTerm: 3,
382				Log: []LogEntry{entry(1, 3, "a"), entry(2, 2, "b")}}, []string{"term"}},
383			{"entry term beyond current", InitialState{CurrentTerm: 2,
384				Log: []LogEntry{entry(1, 3, "a")}}, []string{"currentTerm"}},
385		}
386		for _, tc := range cases {
387			t.Run(tc.name, func(t *testing.T) {
388				expectError(t, tc.initial, nil, tc.fragments...)
389			})
390		}
391	}
392	
393	func TestDeterministicJSONRoundTrip(t *testing.T) {
394		initial := InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}}
395		requests := []AppendRequest{
396			{Term: 3, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 2,
397				Entries: []LogEntry{entry(2, 3, "b")}},
398			{Term: 2, PrevLogIndex: 2, PrevLogTerm: 3}, // stale term
399		}
400		first, err := Replicate(initial, requests)
401		if err != nil {
402			t.Fatal(err)
403		}
404		second, err := Replicate(initial, requests)
405		if err != nil {
406			t.Fatal(err)
407		}
408		if !reflect.DeepEqual(first, second) {
409			t.Fatalf("non-deterministic output:\n%+v\n%+v", first, second)
410		}
411		encoded, err := json.Marshal(first)
412		if err != nil {
413			t.Fatal(err)
414		}
415		var decoded ReplicateOutput
416		if err := json.Unmarshal(encoded, &decoded); err != nil {
417			t.Fatal(err)
418		}
419		if !reflect.DeepEqual(decoded, first) {
420			t.Fatalf("JSON round trip mismatch:\n%+v\n%+v", decoded, first)
421		}
422	}
423	
424	func TestSequentialScenario(t *testing.T) {
425		// 经典场景：领导者连续发送，中间夹一次旧领导者的低任期请求。
426		out := run(t, InitialState{CurrentTerm: 1},
427			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
428				Entries: []LogEntry{entry(1, 1, "set x=1"), entry(2, 1, "set y=2")}},
429			AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 2,
430				Entries: []LogEntry{entry(3, 2, "set z=3")}},
431			AppendRequest{Term: 1, PrevLogIndex: 3, PrevLogTerm: 2}, // 旧领导者，低任期
432			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2, LeaderCommit: 3},
433		)
434		statuses := []bool{true, true, false, true}
435		for i, result := range out.Results {
436			if result.Accepted != statuses[i] {
437				t.Fatalf("result %d = %+v, want accepted=%v", i, result, statuses[i])
438			}
439		}
440		if out.Results[2].Term != 2 {
441			t.Fatalf("stale request changed term: %d", out.Results[2].Term)
442		}
443		want := []LogEntry{entry(1, 1, "set x=1"), entry(2, 1, "set y=2"), entry(3, 2, "set z=3")}
444		if !reflect.DeepEqual(out.FinalLog, want) {
445			t.Fatalf("log = %+v, want %+v", out.FinalLog, want)
446		}
447		if out.FinalCommittedIndex != 3 {
448			t.Fatalf("final commit = %d, want 3", out.FinalCommittedIndex)
